export function decode(spec) {
  const [measure,index='',mount='ND']=spec.split('|');
  const metric=measure.match(/^(\d+)\/(\d+)(ZR|R|B|-)(\d+)$/);
  const inch=measure.match(/^(\d+\.\d+)-(\d+)$/);
  if(!metric&&!inch) throw new Error(`Medida não reconhecida: ${measure}`);
  return {measure,index:index||'ND',mount,rim:Number(metric?metric[4]:inch[2]),width:metric?Number(metric[1]):null,aspect:metric?Number(metric[2]):null,inchWidth:inch?Number(inch[1]):null,construction:metric?({'R':'Radial (R)','ZR':'Radial (ZR)','B':'Diagonal cintado (B)','-':'Hífen na fonte; verificar SKU'}[metric[3]]):'Polegadas; verificar SKU'};
}
export const applications=bikes.flatMap(b=>[['Dianteiro',b.front],['Traseiro',b.rear]].flatMap(([position,spec])=>spec?(Array.isArray(spec)?spec:[spec]).map((s,i)=>({...b,...decode(s),position,alternative:Array.isArray(spec)?`Alternativa ${i+1} expressa no manual`:'Única referência nesta ficha'})):[]));
export const display=s=>!s?'PENDENTE':(Array.isArray(s)?s:[s]).map(x=>x.split('|')[0]).join(' ou ');
